import json, sys
from functools import lru_cache


def apply_ops(state, ops):
    """Apply transaction ops to state (dict). Return new dict or None if any
    observation mismatches."""
    d = dict(state)
    for op in ops:
        kind = op[0]
        if kind == 'get':
            if d.get(op[1]) != op[2]:
                return None
        elif kind == 'put':
            d[op[1]] = op[2]
        elif kind == 'del':
            d.pop(op[1], None)
        elif kind == 'cas':
            _, key, old, new, want = op
            ok = (d.get(key) == old)
            if ok != want:
                return None
            if ok:
                if new is None:
                    d.pop(key, None)
                else:
                    d[key] = new
        elif kind == 'scan':
            got = sorted([[k, v] for k, v in d.items() if op[1] <= k < op[2]])
            if got != op[3]:
                return None
        else:
            return None
    return d


def solve(request):
    txs = request.get('transactions', [])
    initial = request.get('initial', {})
    final = request.get('final', {})
    n = len(txs)
    ids = [t['id'] for t in txs]
    ops = [tuple(tuple(op) for op in t['ops']) for t in txs]
    starts = [t['start'] for t in txs]
    ends = [t['end'] for t in txs]

    # precede[i] = bitmask of transactions that must be committed before i
    precede = [0] * n
    for i in range(n):
        m = 0
        for j in range(n):
            if ends[j] <= starts[i]:
                m |= (1 << j)
        precede[i] = m

    full = (1 << n) - 1
    init_key = tuple(sorted(initial.items()))
    final_key = tuple(sorted(final.items()))

    failed = set()

    def dfs(committed, state_key, order):
        if committed == full:
            return order if state_key == final_key else None
        key = (committed, state_key)
        if key in failed:
            return None
        state = dict(state_key)
        for i in range(n):
            bit = 1 << i
            if committed & bit:
                continue
            if (committed & precede[i]) != precede[i]:
                continue
            new_state = apply_ops(state, ops[i])
            if new_state is None:
                continue
            res = dfs(committed | bit, tuple(sorted(new_state.items())),
                      order + [ids[i]])
            if res is not None:
                return res
        failed.add(key)
        return None

    if n == 0:
        return {'order': [] if dict(init_key) == dict(final_key) else None}
    res = dfs(0, init_key, [])
    return {'order': res}


def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        req = json.loads(line)
        out.write(json.dumps(solve(req)) + '\n')
        out.flush()


if __name__ == '__main__':
    main()
